		/** 
		 * Tests creating a new Rate.
		 */
		public void testCreate() throws Throwable {
			LOGGER.info( "\n======== CREATE ======== ");
			LOGGER.info( "-- Attempting to create a Rate");

			StringBuilder msg = new StringBuilder( "-- Failed to create a Rate" );

			try {            
				Rate entity = RateService.getRateInstance().createRate( generateNewEntity() );
				thePrimaryKey = entity.getRateId();
				LOGGER.info( "-- Successfully created a Rate with primary key" + thePrimaryKey );
			}
			catch (Exception e) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( msg.toString() + " : " + e );

				throw e;
			}
		}

		/** 
		 * Tests reading a Rate. 
		 */
		public Rate testRead() throws Throwable {
			LOGGER.info( "\n======== READ ======== ");
			LOGGER.info( "-- Reading a previously created Rate" );

			Rate entity = null;
			StringBuilder msg = new StringBuilder( "-- Failed to read Rate with primary key" );
			msg.append( thePrimaryKey );
			
			RateFetchOneSummary fetchOneSummary = new RateFetchOneSummary( thePrimaryKey );

			try {
				entity = RateService.getRateInstance().getRate( fetchOneSummary );

				assertNotNull( entity,msg.toString() );

				LOGGER.info( "-- Successfully found Rate " + entity.toString() );
			}
			catch ( Throwable e ) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( msg.toString() + " : " + e );

				throw e;
			}
			
			return entity;
		}

		/** 
		 * Tests updating a Rate.
		 */
		public void testUpdate() throws Throwable {
			LOGGER.info( "\n======== UPDATE ======== ");
			LOGGER.info( "-- Attempting to update a Rate." );

			StringBuilder msg = new StringBuilder( "Failed to update a Rate : " );        
			Rate entity = null;

			try {            
				entity = testRead();

				assertNotNull( entity, msg.toString() );

				LOGGER.info( "-- Now updating the created Rate." );

				// for use later on...
				thePrimaryKey = entity.getRateId();

				RateService proxy = RateService.getRateInstance();            
				proxy.updateRate( entity );   

				LOGGER.info( "-- Successfully saved Rate - " + entity.toString() );
			}
			catch ( Throwable e ) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( msg.toString() + " : primarykey = " + thePrimaryKey + " : entity-" +  entity + " : " + e );

				throw e;
			}
		}

		/** 
		 * Tests deleting a Rate.
		 */
		public void testDelete() throws Throwable {
			LOGGER.info( "\n======== DELETE ======== ");
			LOGGER.info( "-- Deleting a previously created Rate." );

			try{
			    Rate entity = testRead(); 
				RateService.getRateInstance().delete( entity );

				LOGGER.info( "-- Successfully deleted Rate with primary key " + thePrimaryKey );            
			}
			catch ( Throwable e ) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( "-- Failed to delete Rate with primary key " + thePrimaryKey );

				throw e;
			}
		}

		/**
		 * Tests getting all Rates.
		 */
		public void testGetAll() throws Throwable {    
			LOGGER.info( "======== GETALL ======== ");
			LOGGER.info( "-- Retrieving Collection of Rates:" );

			StringBuilder msg = new StringBuilder( "-- Failed to get all Rate : " );        
			List<Rate> collection  = null;

			try {
				// call the static get method on the RateService
				collection = RateService.getRateInstance().getAllRate();

				if ( collection == null || collection.size() == 0 ) {
					LOGGER.warning( unexpectedErrorMsg );
					LOGGER.warning( msg.toString() + " Empty collection returned."  );
				}
				else {
					// Now print out the values
					Rate entity = null;            
					Iterator<Rate> iter = collection.iterator();
					int index = 1;

					while( iter.hasNext() ) {
						// Retrieve the entity   
						entity = iter.next();

						assertNotNull( entity,"-- null entity in Collection." );
						assertNotNull( entity.getRateId(), "-- entity in Collection has a null primary key" );        

						LOGGER.info( " - " + String.valueOf(index) + ". " + entity.toString() );
						index++;
					}
				}
			}
			catch ( Throwable e ) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( msg.toString() + " : " + e );

				throw e;
			}
		}

